/* ===== MINI-GAME: first-contact-hope (Steady the Flame) ===== */
const MG_INSTRUCTOR_LINE="You tend the flame, and those who approach will stay only if it neither flares nor fades.";
const MG={active:false,shown_tip:false,flame:50,target:50,target_drift:0,nomads:[],frame:0,won:false,failed:false};
function mgInit(){MG.active=true;MG.shown_tip=false;MG.flame=50;MG.target=50;MG.target_drift=0;MG.nomads=[];MG.frame=0;MG.won=false;MG.failed=false;
  const angles=[0,0.628,1.257,1.885,2.513,3.142,3.770,4.398,5.027,5.655];for(let i=0;i<10;i++)MG.nomads.push({a:angles[i],d:180,commit:0.5});}
function mgStep(clicked){if(MG.won||MG.failed)return;MG.frame++;
  if(clicked)MG.flame=Math.min(100,MG.flame+12);
  MG.flame=Math.max(0,MG.flame-0.35);MG.target_drift+=0.002;MG.target=50+8*Math.sin(MG.frame*0.017+MG.target_drift);
  const lo=MG.target-8,hi=MG.target+8,steady=MG.flame>=lo&&MG.flame<=hi,too_bright=MG.flame>hi+15,too_dim=MG.flame<lo-15;
  for(const n of MG.nomads){if(steady&&n.d>20){n.d=Math.max(20,n.d-0.6);n.commit=Math.min(1,n.commit+0.008);}
    else if(too_bright){n.d=Math.min(180,n.d+1.2);n.commit=Math.max(0,n.commit-0.015);}
    else if(too_dim){n.d=Math.min(180,n.d+0.8);n.commit=Math.max(0,n.commit-0.01);}
    else if(!steady){n.commit=Math.max(0.3,n.commit-0.002);}}
  if(too_bright){MG.failed=true;MG.fail_mode='flare';return;}
  if(too_dim){MG.failed=true;MG.fail_mode='dim';return;}
  const all_close=MG.nomads.every(n=>n.d<=22);if(all_close&&MG.frame>180)MG.won=true;}
function mgOutcome(){if(MG.won)return'convert_devout';if(MG.failed&&MG.fail_mode==='flare')return'burnout';
  if(MG.failed&&MG.fail_mode==='dim')return'drift_apathy';return'no_effect';}
if(location.hash.includes('mg')){const _origNG=newGame;newGame=function(pole){_origNG(pole);mgInit();};}

