// MG: first-contact-hope trigger & frame seat
if(!MG.active&&!transitioning&&phase==='play'&&SIM.sleep_no===0&&!MG.shown_tip){let grey_near=0;for(const x of SIM.npcs)if(x.tribe===-1&&cheb(x.pos,SIM.player_pos)<=6)grey_near++;
  if(grey_near>=8){mgInit();if(!MG.shown_tip){setTip(MG_INSTRUCTOR_LINE);MG.shown_tip=true;}}}
if(MG.active&&!MG.won&&!MG.failed){const ptr=this.input.activePointer;const clicked=ptr.isDown&&ptr.getDuration()<100;
  mgStep(clicked);const px=SIM.player_pos[0]*CELL+CELL/2,py=SIM.player_pos[1]*CELL+CELL/2;
  this.overlay.fillStyle(0x000000,0.6);this.overlay.fillRect(0,0,VIEW,VIEW);
  const fCore=MG.flame>MG.target+15?0xffffff:(MG.flame<MG.target-15?0xff4400:0xffcc44);
  const fRad=4+MG.flame*0.12;this.overlay.fillStyle(fCore,0.9);this.overlay.fillCircle(px,py-12,fRad);
  this.overlay.fillStyle(fCore,0.3);this.overlay.fillCircle(px,py-12,fRad*2.2);
  for(const n of MG.nomads){const nx=px+Math.cos(n.a)*n.d,ny=py+Math.sin(n.a)*n.d;const sz=6+n.commit*4;
    const col=n.commit>0.7?0xccaa66:0x666666;this.overlay.fillStyle(col,0.6+n.commit*0.3);this.overlay.fillCircle(nx,ny,sz);
    if(n.d>22){this.overlay.lineStyle(1,col,0.4);this.overlay.lineBetween(nx,ny,nx+(px-nx)*0.15,ny+(py-ny)*0.15);}}}
if(MG.active&&(MG.won||MG.failed)){MG.frame++;if(MG.frame>60){const oc=mgOutcome();if(oc==='convert_devout'){for(let i=0;i<3;i++){const x=SIM.npcs.find(n=>n.tribe===-1&&cheb(n.pos,SIM.player_pos)<=6);if(x){x.tribe=0;x.v=10;x.I=10;x.ever_nonzero=true;}}}
    else if(oc==='burnout'){const x=SIM.npcs.find(n=>n.tribe===-1&&cheb(n.pos,SIM.player_pos)<=6);if(x)x.burn=true;}
    else if(oc==='drift_apathy'){for(let i=0;i<2;i++){const x=SIM.npcs.find(n=>n.tribe===-1&&cheb(n.pos,SIM.player_pos)<=6);if(x){x.v=0;x.I=0;}}}
    MG.active=false;MG.frame=0;}}

