// M1: mgStep brightens flame on click, decays otherwise
mgInit();const f0=MG.flame;mgStep(true);const f1=MG.flame;mgStep(false);const f2=MG.flame;
out.push(['M1 flame: click brightens, decay dims', f1>f0&&f2<f1, `${f0.toFixed(1)}->${f1.toFixed(1)}->${f2.toFixed(1)}`]);
// M2: too bright -> fail flare, too dim -> fail dim
mgInit();MG.flame=85;for(let i=0;i<10;i++)mgStep(false);
const flare=MG.failed&&MG.fail_mode==='flare';mgInit();MG.flame=10;for(let i=0;i<10;i++)mgStep(false);
const dim=MG.failed&&MG.fail_mode==='dim';
out.push(['M2 fail modes: flare when too bright, dim when too dim', flare&&dim, `flare=${flare} dim=${dim}`]);
